package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Real;
    in attribute io_2 : Boolean;
    in attribute io_3 : Boolean;
    in attribute io_7 : Integer;
    attribute autoMode : Boolean := true;
    attribute manualAnglePercent : Integer := 0;
    attribute prevBtn2 : Boolean := false;
    attribute prevBtn3 : Boolean := false;
    attribute curAnglePercent : Integer := 0;
    attribute lightMode : Boolean := false;
    perform action tick {
      first start;
      then if autoMode {
        first start;
        then if ((io_1) >= (30.0)) {
          first start;
          then assign curAnglePercent := 0;
          then assign lightMode := false;
        } else {
          first start;
          then if ((io_0) <= (400.0)) {
            first start;
            then assign curAnglePercent := 100;
            then assign lightMode := true;
          } else {
            first start;
            then assign curAnglePercent := 0;
            then assign lightMode := false;
          }
        }
      }
      then if (not autoMode) {
        first start;
        then assign curAnglePercent := manualAnglePercent;
      }
      then if ((io_2) and ((not prevBtn2))) {
        first start;
        then assign autoMode := (if autoMode ? false else true);
      }
      then if ((io_3) and ((not prevBtn3))) {
        first start;
        then if (not autoMode) {
          first start;
          then assign manualAnglePercent := (if ((manualAnglePercent) == (100)) ? 0 else manualAnglePercent + 10);
        }
      }
      then assign prevBtn2 := io_2;
      then assign prevBtn3 := io_3;
    }
    out attribute io_4 : Boolean = lightMode;
    out attribute io_5 : Real = (if ((curAnglePercent) >= (0)) ? (if ((curAnglePercent) <= (100)) ? curAnglePercent else 100.0) else 0.0);
    out attribute io_6 : Integer = (if ((curAnglePercent) <= (100)) ? (if ((curAnglePercent) >= (0)) ? curAnglePercent else 0) else 100);
  }
  part system : Controller;
}
